'use strict';

// MODULES //

var tape = require( 'tape' );
var toFloat32 = require( '@stdlib/number-float64-base-to-float32' );
var isSameValue = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof isSameValue, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `true` if provided two single-precision floating-point numbers which are the same value', function test( t ) {
	var values;
	var i;

	values = [
		toFloat32( 5.0 ),
		toFloat32( 3.14 ),
		toFloat32( -3.14 ),
		toFloat32( 0.0 ),
		toFloat32( -0.0 ),
		toFloat32( NaN )
	];
	for ( i = 0; i < values.length; i++ ) {
		t.strictEqual( isSameValue( values[ i ], values[ i ] ), true, 'returns expected value when provided '+values[ i ] );
	}
	t.end();
});

tape( 'the function returns `false` if not provided two single-precision floating-point numbers which are the same value', function test( t ) {
	var a;
	var b;
	var i;

	a = [
		toFloat32( 5.0 ),
		toFloat32( 3.14 ),
		toFloat32( -3.14 ),
		toFloat32( 0.0 ),
		toFloat32( -0.0 )
	];
	b = [
		toFloat32( -5.0 ),
		toFloat32( -3.14 ),
		toFloat32( 3.14 ),
		toFloat32( -0.0 ),
		toFloat32( 0.0 )
	];
	for ( i = 0; i < a.length; i++ ) {
		t.strictEqual( isSameValue( a[ i ], b[ i ] ), false, 'returns expected value when provided '+a[ i ]+' and '+b[ i ] );
	}
	t.end();
});","lineStart":1,"lineEnd":77,"totalLines":77,"truncated":false}},"title":"repos/pc-lib-3456/number-float32-base-assert-is-same-value/test/test.js","time":{"start":1783263856072,"end":1783263856076}},"id":"prt_f32cf048e001Ld0M5dX6YilmQc","sessionID":"ses_0cd318511ffeMHP0x27LkbqHgP","messageID":"msg_f32cefcbb0011RYuAoW89hxeTR"}}

